가격 = {"사과": 1000, "귤": 500, "포도": 3000, "배": 2000}
답 = input("산 것: ")
합 = 0
for 물건 in 답.split():
    if 물건 in 가격:
        합 += 가격[물건]
    else:
        print(물건, "없어요")
print(합, "원")

