단어장 = {"apple": "사과", "dog": "개"}
while True:
    낱말 = input("낱말: ")
    if 낱말 == "끝":
        break
    if 낱말 in 단어장:
        print(단어장[낱말])
    else:
        뜻 = input("뜻: ")
        단어장[낱말] = 뜻
        print("넣었어요")
print("낱말", len(단어장), "개")
